-- Nexus feature and safety migration, applied to project cqigyqrmmtjsikcgmriq.
-- Module discussion comments use an explicit module type and are only readable for public records.
create table if not exists public.module_comments (id uuid primary key default gen_random_uuid(),module_type text not null check(module_type in ('debates','courses','ideas','projects')),item_id uuid not null,author_id uuid not null references public.profiles(id) on delete cascade,body text not null check(length(body) between 1 and 3000),created_at timestamptz not null default now());
create index if not exists module_comments_item_idx on public.module_comments(module_type,item_id,created_at);
alter table public.module_comments enable row level security;
create policy "public module comments readable" on public.module_comments for select to anon,authenticated using(case module_type when 'debates' then exists(select 1 from public.debates x where x.id=item_id and x.visibility='public') when 'courses' then exists(select 1 from public.courses x where x.id=item_id and x.visibility='public') when 'ideas' then exists(select 1 from public.ideas x where x.id=item_id and x.visibility='public') when 'projects' then exists(select 1 from public.projects x where x.id=item_id and x.visibility='public') else false end);
create policy "authenticated users comment on public modules" on public.module_comments for insert to authenticated with check(author_id=(select auth.uid()) and case module_type when 'debates' then exists(select 1 from public.debates x where x.id=item_id and x.visibility='public') when 'courses' then exists(select 1 from public.courses x where x.id=item_id and x.visibility='public') when 'ideas' then exists(select 1 from public.ideas x where x.id=item_id and x.visibility='public') when 'projects' then exists(select 1 from public.projects x where x.id=item_id and x.visibility='public') else false end);
create policy "comment owners or admins delete module comments" on public.module_comments for delete to authenticated using(author_id=(select auth.uid()) or private.is_admin());
grant select,insert,delete on public.module_comments to anon,authenticated;

create policy "admins delete debates" on public.debates for delete to authenticated using(private.is_admin());
create policy "admins delete courses" on public.courses for delete to authenticated using(private.is_admin());
create policy "admins delete ideas" on public.ideas for delete to authenticated using(private.is_admin());
create policy "admins delete projects" on public.projects for delete to authenticated using(private.is_admin());
create policy "admins delete comments" on public.comments for delete to authenticated using(private.is_admin());
create policy "course authors manage lessons" on public.course_lessons for all to authenticated using(exists(select 1 from public.courses c where c.id=course_id and (c.author_id=(select auth.uid()) or private.is_admin()))) with check(exists(select 1 from public.courses c where c.id=course_id and (c.author_id=(select auth.uid()) or private.is_admin())));
create policy "admins manage course reviews" on public.course_reviews for delete to authenticated using(private.is_admin());
create policy "course owner reads enrolled lessons" on public.course_lessons for select to authenticated using(exists(select 1 from public.courses c where c.id=course_id and (c.visibility='public' or c.author_id=(select auth.uid()) or exists(select 1 from public.course_enrollments e where e.course_id=c.id and e.user_id=(select auth.uid())))));
create policy "course resource files read" on storage.objects for select to authenticated using(bucket_id='nexus-media' and exists(select 1 from public.course_lessons l join public.courses c on c.id=l.course_id where l.file_path=name and (c.visibility='public' or c.author_id=(select auth.uid()) or exists(select 1 from public.course_enrollments e where e.course_id=c.id and e.user_id=(select auth.uid())))));
create policy "course resource upload own folder" on storage.objects for insert to authenticated with check(bucket_id='nexus-media' and (storage.foldername(name))[1]=(select auth.uid())::text);

create policy "users create notifications as actor" on public.notifications for insert to authenticated with check(actor_id=(select auth.uid()) and user_id<>(select auth.uid()));
create or replace function public.notify_follow() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$ begin insert into public.notifications(user_id,actor_id,kind,entity_id,message) values(new.following_id,new.follower_id,'follow',new.follower_id,'Seni takip etmeye başladı.'); return new; end $$;
create or replace function public.notify_like() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$ declare recipient uuid; begin select author_id into recipient from public.posts where id=new.post_id; if recipient is not null and recipient<>new.user_id then insert into public.notifications(user_id,actor_id,kind,entity_id,message) values(recipient,new.user_id,'like',new.post_id,'Gönderini beğendi.'); end if; return new; end $$;
create or replace function public.notify_comment() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$ declare recipient uuid; begin select author_id into recipient from public.posts where id=new.post_id; if recipient is not null and recipient<>new.author_id then insert into public.notifications(user_id,actor_id,kind,entity_id,message) values(recipient,new.author_id,'comment',new.post_id,'Gönderine yorum yaptı.'); end if; return new; end $$;
create or replace function public.notify_message() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$ begin insert into public.notifications(user_id,actor_id,kind,entity_id,message) select cm.user_id,new.sender_id,'message',new.conversation_id,'Sana özel mesaj gönderdi.' from public.conversation_members cm where cm.conversation_id=new.conversation_id and cm.user_id<>new.sender_id; return new; end $$;
create or replace function public.notify_module_comment() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$ declare recipient uuid; begin if new.module_type='debates' then select author_id into recipient from public.debates where id=new.item_id; elsif new.module_type='courses' then select author_id into recipient from public.courses where id=new.item_id; elsif new.module_type='ideas' then select author_id into recipient from public.ideas where id=new.item_id; else select author_id into recipient from public.projects where id=new.item_id; end if; if recipient is not null and recipient<>new.author_id then insert into public.notifications(user_id,actor_id,kind,entity_id,message) values(recipient,new.author_id,'module_comment',new.item_id,'İçeriğine yorum yaptı.'); end if; return new; end $$;
revoke all on function public.notify_follow() from public,anon,authenticated;
revoke all on function public.notify_like() from public,anon,authenticated;
revoke all on function public.notify_comment() from public,anon,authenticated;
revoke all on function public.notify_message() from public,anon,authenticated;
revoke all on function public.notify_module_comment() from public,anon,authenticated;
drop trigger if exists notify_new_follow on public.follows;create trigger notify_new_follow after insert on public.follows for each row execute function public.notify_follow();
drop trigger if exists notify_new_like on public.post_likes;create trigger notify_new_like after insert on public.post_likes for each row execute function public.notify_like();
drop trigger if exists notify_new_comment on public.comments;create trigger notify_new_comment after insert on public.comments for each row execute function public.notify_comment();
drop trigger if exists notify_new_message on public.messages;create trigger notify_new_message after insert on public.messages for each row execute function public.notify_message();
drop trigger if exists notify_new_module_comment on public.module_comments;create trigger notify_new_module_comment after insert on public.module_comments for each row execute function public.notify_module_comment();

create table public.ai_request_limits(user_id uuid not null references auth.users(id) on delete cascade,request_day date not null default current_date,request_count integer not null default 0 check(request_count between 0 and 20),primary key(user_id,request_day));
alter table public.ai_request_limits enable row level security;
revoke all on public.ai_request_limits from public,anon,authenticated;
create or replace function private.consume_ai_request() returns boolean language plpgsql volatile security definer set search_path=pg_catalog,public,auth as $$ declare allowed boolean:=false; begin if auth.uid() is null then return false; end if; insert into public.ai_request_limits(user_id,request_day,request_count) values(auth.uid(),current_date,1) on conflict(user_id,request_day) do update set request_count=public.ai_request_limits.request_count+1 where public.ai_request_limits.request_count<20 returning true into allowed; return coalesce(allowed,false); end $$;
revoke all on function private.consume_ai_request() from public,anon,authenticated;
grant execute on function private.consume_ai_request() to authenticated;
create or replace function public.consume_ai_request() returns boolean language sql volatile security definer set search_path=pg_catalog,private,auth as $$ select private.consume_ai_request() $$;
revoke all on function public.consume_ai_request() from public,anon;
grant execute on function public.consume_ai_request() to authenticated;
